from src.workflow import Session

class Env:
    def __init__(self): self.listeners={}; self.log=[]; self.deferred=[]
    def bind(self, cb): return cb
    def call(self, method, *args):
        arg=args[0] if args else None
        if method == 'listen':
            token, cb=args; self.listeners.setdefault(token,[]).append(cb); return cb
        if method == 'unlisten':
            token, cb=args; self.listeners[token].remove(cb)
        elif method == 'start':
            for cb in list(self.listeners.get(arg, [])): cb({'cached': True})
        elif method == 'decode':
            token, packet, done=args
            if packet.get('defer'):
                self.deferred.append((done, {'seq': packet['seq']})); return {'deferred': True}
            return {'deferred': False, 'frame': {'seq': packet.get('seq', 0)}}
        elif method in ('recordProgress','showProgress','record','showQueued','transport','cancel'):
            self.log.append((method,arg))

