from src.workflow import Session

class Env:
    def __init__(self): self.listeners=[]; self.log=[]; self.session=None; self.navigated=False
    def bind(self, cb): return cb
    def call(self, method, *args):
        if method == 'listen':
            token, cb=args; self.listeners.append((token,cb)); return cb
        if method == 'unlisten':
            token, cb=args
            if (token,cb) in self.listeners:self.listeners.remove((token,cb))
        elif method == 'start':
            token=args[0]
            snapshot=[cb for t,cb in self.listeners if t==token]
            for cb in snapshot: cb({'seq': 1})
            # Source retains a callback snapshot and emits again before start returns.
            for cb in snapshot: cb({'seq': 2})
        elif method == 'decode':
            token, packet, done=args; return {'deferred':False,'frame':packet}
        elif method == 'showProgress':
            self.log.append((method,args[0]))
            if not self.navigated:
                self.navigated=True; self.session.hide()
        elif method in ('recordProgress','record','showQueued','transport','cancel'):
            self.log.append((method,args[0]))

e=Env(); s=Session(e); e.session=s
f={'id':'a','token':'a','feed':True}; s.select(f)
assert [x for x in e.log if x[0]=='recordProgress'] == [('recordProgress', {'fileId':'a','attemptId':1,'frame':{'seq':1}})]
assert [x for x in e.log if x[0]=='showProgress'] == [('showProgress', {'fileId':'a','attemptId':1,'frame':{'seq':1}})]
assert not e.listeners
print('synchronous-navigation admission smoke test passed')
